<?php
require __DIR__.'/app/bootstrap.php';
maintenance_gate(); member_required();
if(setting('maintenance_mode','1')==='1' && !is_admin()){http_response_code(403);exit('Створення тем закрите до запуску форуму.');}
$cats=db()->query('SELECT id,title FROM categories WHERE is_visible=1 ORDER BY sort_order')->fetchAll();$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$title=trim((string)($_POST['title']??''));$body=trim((string)($_POST['body']??''));$cat=(int)($_POST['category_id']??0);if($title===''||$body===''||!in_array($cat,array_map('intval',array_column($cats,'id')),true)){$error='Заповни всі поля.';}else{$slug=trim(preg_replace('/[^a-z0-9]+/','-',strtolower(iconv('UTF-8','ASCII//TRANSLIT//IGNORE',$title)?:'tema')),'-').'-'.substr(bin2hex(random_bytes(3)),0,6);$st=db()->prepare('INSERT INTO topics(category_id,user_id,title,slug,body,last_activity_at) VALUES(?,?,?,?,?,CURRENT_TIMESTAMP)');$st->execute([$cat,current_user_id(),$title,$slug,$body]);header('Location:/topic.php?slug='.urlencode($slug));exit;}}
$selectedCategory=(int)($_POST['category_id']??$_GET['category_id']??0);
forum_header('Створити тему');?><section class="page-title"><a href="/">← Форум</a><h1>Нова тема</h1></section><?php if($error):?><div class="notice danger"><?=e($error)?></div><?php endif;?><form method="post" class="panel stack settings-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>Розділ<select name="category_id" required><option value="">Оберіть</option><?php foreach($cats as $c):?><option value="<?=e((string)$c['id'])?>" <?=$selectedCategory===(int)$c['id']?'selected':''?>><?=e($c['title'])?></option><?php endforeach;?></select></label><label>Назва теми<input name="title" required></label><label>Перше повідомлення<textarea name="body" rows="8" required></textarea></label><button class="btn primary">Опублікувати</button></form><?php forum_footer(); ?>
